import java.util.Arrays;

public final class BubbleSortDemo {
    private static final String SORTED_PREFIX = "Sorted array: ";
    private static final int[] SAMPLE_VALUES = { 64, 34, 25, 12, 22, 11, 90 };
    private static final String USAGE = "Usage: java BubbleSortDemo [integers...]";

    private BubbleSortDemo() {
        // Utility class; do not instantiate.
    }

    public static void main(String[] args) {
        int[] values = resolveValues(args);
        if (values == null) {
            return;
        }

        BubbleSort.sort(values);
        System.out.println(SORTED_PREFIX);
        System.out.println(Arrays.toString(values));
    }

    private static int[] resolveValues(String[] args) {
        if (args.length == 0) {
            return Arrays.copyOf(SAMPLE_VALUES, SAMPLE_VALUES.length);
        }

        return parseValues(args);
    }

    private static int[] parseValues(String[] args) {
        int[] values = new int[args.length];

        for (int i = 0; i < args.length; i++) {
            try {
                values[i] = Integer.parseInt(args[i]);
            } catch (NumberFormatException ex) {
                System.err.println("Invalid integer at argument " + (i + 1) + ": \"" + args[i] + "\"");
                System.err.println(USAGE);
                return null;
            }
        }

        return values;
    }
}

